CREATE OR REPLACE FUNCTION realtime.send(payload jsonb, event text, topic text, private boolean DEFAULT true)
RETURNS void
AS $$
DECLARE
partition_name text;
partition_start timestamp;
partition_end timestamp;
BEGIN
  partition_start := date_trunc('day', NOW());
  partition_end := partition_start + interval '1 day';
  partition_name := 'messages_' || to_char(partition_start, 'YYYY_MM_DD');

  BEGIN
    EXECUTE format(
      'CREATE TABLE IF NOT EXISTS realtime.%I PARTITION OF realtime.messages F

TRUNCATE TABLE
  public.table_adjacencies,
  public.table_merge_graph,
  public.table_inventory,
  public.allowed_capacities,
  public.zones,
  public.restaurant_capacity_rules,
  public.restaurant_turn_bands,
  public.restaurant_operating_hours,
  public.restaurant_service_periods,
  public.booking_occasions,
  public.service_policy,
  public.merge_rules,
  public.strategic_configs,
  public.restaurants
RESTART IDENTITY
CASCADE

CREATE OR REPLACE FUNCTION pg_temp.count_estimate(
    query text
) RETURNS integer LANGUAGE plpgsql AS $$
DECLARE
    plan jsonb;
BEGIN
    EXECUTE 'EXPLAIN (FORMAT JSON)' || query INTO plan;
    RETURN plan->0->'Plan'->'Plan Rows';
END;
$$
